with open('text.gcode') as f:
    lines = f.readlines()

capturing = False
coords = []
x, y = 0.0, 0.0
for line in lines:
    if 'M486 AEmbossed text' in line:
        capturing = True
        continue
    elif capturing and 'M486 S-1' in line:
        break
    if capturing:
        parts = line.split()
        for p in parts:
            if p.startswith('X'): x = float(p[1:])
            elif p.startswith('Y'): y = float(p[1:])
        if 'E' in line and any(p.startswith('E') and float(p[1:]) > 0 for p in parts):
            coords.append((x, y))

if coords:
    xs = [c[0] for c in coords]
    ys = [c[1] for c in coords]
    print('X range:', min(xs), max(xs))
    print('Y range:', min(ys), max(ys))
    # Simple ASCII art
    min_x, max_x = min(xs), max(xs)
    min_y, max_y = min(ys), max(ys)
    w, h = 60, 20
    grid = [[' ' for _ in range(w)] for _ in range(h)]
    for x, y in coords:
        ix = int((x - min_x) / (max_x - min_x + 1e-5) * (w - 1))
        iy = int((y - min_y) / (max_y - min_y + 1e-5) * (h - 1))
        grid[h - 1 - iy][ix] = '#'
    for row in grid:
        print(''.join(row))
